fn total(price: i32, quantity: i32) -> Result<i32, &'static str> {
    if price < 0 || quantity < 0 { return Err("Negative value"); }
    price.checked_mul(quantity).ok_or("Total too large")
}
fn main() {
    println!("{}", total(12, 3).expect("valid input"));
    println!("{}", total(12, 0).expect("valid input"));
    match total(12, -1) {
        Err(_) => println!("Invalid input rejected"),
        Ok(value) => println!("Unexpected: {}", value),
    }
}

